        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
        return;
      }
      break;
    case 'array': {
      if (!Array.isArray(value)) {
        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
