  });
  const invalid = await runReach(invalidScene, '/x');
  assert.equal(invalid.code, 2, '整份场景严格校验失败时不得输出报告');
  assert.equal(invalid.stdout, '');
  assert.ok(invalid.stderr.includes('invalid.json'));
});

